const codigo = Object.keys(codigos).find((c) => msg.includes(c)) || (msg.includes('invalid input syntax for type uuid') ? 'NAO_ENCONTRADO' : null);
return resposta(codigo ? codigos[codigo] : 500, { codigo: codigo || 'ERRO' });

